recipes.code:
{
  "inputs": [
    {
      "id": "cellarion-token",
      "type": "promptString",
      "description": "Personal API token from Settings -> API tokens (starts with cel_).",
      "password": true
    }
  ],
  "servers": {
    "cellarion": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "cellarion-mcp@0.1.1"
      ],
      "env": {
        "CELLARION_TOKEN": "${input:cellarion-token}",
        "CELLARION_URL": "https://cellarion.app"
      }
    }
  }
}
